#include "ship_hull_material.hpp"
#include <fstream>
#include <iostream>
#include <chrono>
using namespace storm_ship_laser;
namespace cv=storm::ship::material::convex;
void graph(std::ofstream&out,const cv::State&s){for(const auto&c:s.cells){uint32_t n=c?c->edges.size():0;out.write((char*)&n,4);if(c)for(const auto&row:c->edges){n=row.size();out.write((char*)&n,4);for(auto k:row){out.write((char*)&k.cell,4);out.write((char*)&k.piece,4);}}}for(auto&c:s.components){uint32_t n=c.pieces.size();out.write((char*)&c.authoredOwner,4);out.write((char*)&n,4);for(auto k:c.pieces){out.write((char*)&k.cell,4);out.write((char*)&k.piece,4);}}}
int main(int argc,char**argv){std::ifstream f(argv[1]);Mesh mesh;int id;Triangle tri;while(f>>id){for(auto&v:tri)f>>v.position.x>>v.position.y>>v.position.z>>v.normal.x>>v.normal.y>>v.normal.z>>v.uv[0]>>v.uv[1];mesh[id].push_back(tri);}const std::map<int,float> wood{{0,.22f},{1,.18f}};auto surface=timberSurface(mesh,wood);auto cells=std::make_shared<MaterialCells>();cells->source=storm::ship::material::cellSource(surface,wood);surface.cells=cells;auto layout=storm_ship_structure::build(surface,wood);surface.structure=std::make_shared<const storm_ship_structure::State>(storm_ship_structure::seed(layout,surface,wood));auto start=std::chrono::steady_clock::now();if(!storm::ship::material::preparePhysicalCache(surface))return 2;auto elapsed=[&]{return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();};std::cout<<"physical_ms="<<elapsed()<<" ";std::ofstream out(argv[2],std::ios::binary);graph(out,*surface.cells->convex);auto warm=cv::ready(surface.cells,layout);if(warm!=surface.cells)return 3;
 cv::Cut cut;bool found=false;for(const auto&c:surface.cells->convex->cells){if(!c)continue;for(const auto&p:*c->pieces)if(p.volume>.0001){auto center=cv::center(p);float r=.04f;cut.bounds={center-Vec3{r,r,r},center+Vec3{r,r,r}};for(unsigned axis=0;axis<3;++axis){auto v=storm_ship_structure::axisVector(axis,1);float x=storm_ship_structure::coordinate(center,axis);cut.planes.push_back({v,x+r});cut.planes.push_back({v*-1.f,-x+r});}found=true;break;}if(found)break;}if(!found)return 4;start=std::chrono::steady_clock::now();auto edit=cv::edit(surface.cells,{cut});if(!edit.complete||edit.changed.empty())return 5;std::cout<<"edit_ms="<<elapsed()<<" changed="<<edit.changed.size()<<" ";graph(out,*edit.cells->convex);for(auto id:edit.changed){storm::ship::material::Writer w;w.mesh(*edit.cells->changed.at(id));uint32_t n=w.bytes.size();out.write((char*)&id,4);out.write((char*)&n,4);out.write((char*)w.bytes.data(),n);}auto saved=edit.cells;auto cold=std::make_shared<MaterialCells>(*saved);cold->convex.reset();start=std::chrono::steady_clock::now();auto restored=cv::ready(cold,layout);if(!restored||!cv::compatible(*restored))return 6;std::cout<<"restore_ms="<<elapsed()<<" components="<<restored->convex->components.size()<<"\n";graph(out,*restored->convex);return 0;}
